using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CrossingUVAudit{static CrossingUVAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CrossingUVAudit.request"))return;File.Delete("CrossingUVAudit.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var log=new List<string>();foreach(var f in roads.GetComponentsInChildren<MeshFilter>().Where(f=>f.sharedMesh&&f.GetComponent<Renderer>()&&(f.name=="Line020"||f.name=="Line021"||f.name.StartsWith("Line")))){var r=f.GetComponent<Renderer>();var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);log.Add(f.name+" path="+AnimationUtility.CalculateTransformPath(f.transform,roads.transform)+" bbox="+r.bounds+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" mats="+string.Join(",",r.sharedMaterials.Where(m=>m).Select(m=>m.name)));for(int c=0;c<8;c++)if(uv[c]!=null)log.Add(" UV"+c+" range="+uv[c].Min(q=>q.x)+","+uv[c].Max(q=>q.x)+" / "+uv[c].Min(q=>q.y)+","+uv[c].Max(q=>q.y));if(f.name=="Line020"||f.name=="Line021"){for(int i=0;i<Math.Min(p.Length,30);i++)log.Add(" v "+f.transform.TransformPoint(p[i])+" UV="+uv[0][i]);var b=r.bounds;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,b.center+Vector3.up*65,b.center,"Crossing-Before-"+f.name});}}File.WriteAllLines("FinalEnvironmentRoadReview/CrossingUVAudit.txt",log);}}
